def hidden_rule_fn(state):
    n = len(state)
    if n == 0:
        return state[:]

    def is_prime(k):
        if k < 2:
            return False
        if k == 2:
            return True
        if k % 2 == 0:
            return False
        for i in range(3, int(k**0.5) + 1, 2):
            if k % i == 0:
                return False
        return True

    a = state[-2]
    b = state[-1]

    if is_prime(n):
        new_val = (a ^ b) % 7
    else:
        new_val = (a + b + 3) % 7

    return state + [new_val]
